ii={x['id']:x for x in items};cc={x['id']:x for x in claims};problems=[];problemkeys={}
def P(key,title,iks,cks,as_stated,today,art,worth,why=None):
    ident=f'P56-P{len(problems)+1:03d}';problemkeys[key]=ident
    src=[ii[groups[k]] for k in iks];cs=[cc[claimkeys[k]] for k in cks]
    occ={json.dumps(l,sort_keys=True):l for i in src for l in i['lines']}
    problems.append(dict(id=ident,title=title,occurrences=list(occ.values()),as_he_states=as_stated,plausible_today=today,state_of_art=art,why_open=why or 'No checked historical source states why this particular formulation was left open. The manuscript’s local doubt and the stated hypothesis gaps are the evidence; no motivational history is invented.',worth=worth,refs=sorted({r for c in cs for r in c['refs']}),items=[i['id'] for i in src],claims=[c['id'] for c in cs],as_of=DATE,internal_key=key))
